SELECT p.post_id, p.user_id, p.category, p.title, p.views, p.created_at, p.is_anonymous AS anonymous, CASE WHEN p.is_anonymous = 1 THEN '익명' ELSE u.user_name END AS author_name, (SELECT COUNT(*) FROM comments c WHERE c.post_id = p.post_id) AS comment_count, (SELECT COUNT(*) FROM post_likes pl WHERE pl.post_id = p.post_id) AS likes FROM posts p JOIN users u ON p.user_id = u.user_id
p.category = #{category}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.views DESC, p.created_at DESC ORDER BY likes DESC, p.created_at DESC ORDER BY p.created_at DESC
LIMIT #{size} OFFSET #{offset}

